// Generated by litert-google-tensor (scripts/package_litertlm.py).
// Loads a Google Tensor-compiled .litertlm generative LLM/VLM bundle on
// packaged Pixels (Tensor G5 / Tensor G6) using Backend.NPU, and falls back
// to Backend.CPU when NPU initialization fails or on unsupported devices.
package com.yunha.remy

import android.content.Context
import android.os.Build
import android.os.SystemClock
import android.util.Log
import com.google.ai.edge.litertlm.Backend
import com.google.ai.edge.litertlm.Content
import com.google.ai.edge.litertlm.Contents
import com.google.ai.edge.litertlm.Conversation
import com.google.ai.edge.litertlm.ConversationConfig
import com.google.ai.edge.litertlm.Engine
import com.google.ai.edge.litertlm.EngineConfig
import com.google.ai.edge.litertlm.Message
import com.google.ai.edge.litertlm.ToolProvider
import java.io.File
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.withContext
import org.json.JSONObject

object TensorLmLoader {
  private const val TAG = "LiteRtTensor"
  private const val MODEL_NAME = "gemma-4-E2B-it"
  private const val DELIVERY_MODE = "sideload"
  private const val FALLBACK_FILE = ""
  private const val VISION_ON_NPU = true
  private const val AUDIO_ON_NPU = true
  private val PACKAGED_SOC_MODELS = setOf("Tensor G5", "Tensor G6")

  enum class Path {
    /** The Google Tensor .litertlm bundle initialized on the Pixel TPU (Backend.NPU). */
    NPU,
    /** Fallback execution on the CPU (Backend.CPU). */
    CPU,
  }

  class LoadedLm(
    val engine: Engine,
    val path: Path,
    val modelFile: File,
    val loadTimeMs: Long,
    val npuError: String? = null,
  ) : AutoCloseable {

    /** Creates a multi-turn Conversation on the initialized Engine. */
    fun createConversation(
      systemInstruction: String? = null,
      tools: List<ToolProvider> = emptyList(),
    ): Conversation {
      val config =
        ConversationConfig(
          systemInstruction = systemInstruction?.let { Contents.of(it) },
          tools = tools,
        )
      return engine.createConversation(config)
    }

    /** Sends a prompt (and optional PNG/JPEG bytes for VLM bundles) and streams Message chunks. */
    fun sendMessageAsync(
      conversation: Conversation,
      prompt: String,
      imageBytes: ByteArray? = null,
    ): Flow<Message> {
      val items = mutableListOf<Content>(Content.Text(prompt))
      if (imageBytes != null) {
        if (VISION_ON_NPU) {
          items.add(Content.ImageBytes(imageBytes))
        } else {
          Log.w(TAG, "Image ignored: this .litertlm bundle has no vision encoder.")
        }
      }
      return conversation.sendMessageAsync(Contents.of(items))
    }

    override fun close() {
      engine.close()
    }
  }

  /**
   * Resolves the `.litertlm` bundle on disk and initializes the LiteRT-LM [Engine].
   *
   * Call from a background coroutine (`Dispatchers.IO`). Close the returned [LoadedLm]
   * when done.
   */
  suspend fun load(
    context: Context,
    maxNumTokens: Int? = null,
  ): LoadedLm =
    withContext(Dispatchers.IO) {
      val appContext = context.applicationContext
      val started = SystemClock.elapsedRealtime()
      val cacheDir = File(appContext.cacheDir, "litertlm_cache").apply { mkdirs() }.absolutePath
      val npuUnsupported = npuUnsupportedReason()
      var npuError: String? = npuUnsupported

      if (npuUnsupported == null) {
        try {
          val socTag = Build.SOC_MODEL.replace(' ', '_')
          val modelFile = resolveModelFile(appContext, "${MODEL_NAME}_Google_${socTag}.litertlm")
          val nativeLibDir = appContext.applicationInfo.nativeLibraryDir
          val npuBackend = Backend.NPU(nativeLibraryDir = nativeLibDir)
          val config =
            EngineConfig(
              modelPath = modelFile.absolutePath,
              backend = npuBackend,
              visionBackend = if (VISION_ON_NPU) npuBackend else null,
              audioBackend = if (AUDIO_ON_NPU) npuBackend else null,
              maxNumTokens = maxNumTokens,
              cacheDir = cacheDir,
            )
          val engine = Engine(config)
          engine.initialize()
          return@withContext finish(
            engine = engine,
            path = Path.NPU,
            modelFile = modelFile,
            started = started,
            npuError = null,
          )
        } catch (e: Exception) {
          npuError = "${e.javaClass.simpleName}: ${e.message}"
          Log.w(
            TAG,
            "Google Tensor NPU initialization for $MODEL_NAME failed ($npuError); falling back to CPU",
            e,
          )
        }
      } else {
        Log.i(TAG, "Skipping NPU for $MODEL_NAME ($npuUnsupported); using CPU")
      }

      val fallbackName =
        if (FALLBACK_FILE.isNotEmpty()) {
          FALLBACK_FILE
        } else {
          val socTag = Build.SOC_MODEL.replace(' ', '_')
          "${MODEL_NAME}_Google_${socTag}.litertlm"
        }
      val cpuFile = resolveModelFile(appContext, fallbackName)
      val cpuConfig =
        EngineConfig(
          modelPath = cpuFile.absolutePath,
          backend = Backend.CPU(),
          visionBackend = if (VISION_ON_NPU) Backend.CPU() else null,
          audioBackend = if (AUDIO_ON_NPU) Backend.CPU() else null,
          maxNumTokens = maxNumTokens,
          cacheDir = cacheDir,
        )
      val engine = Engine(cpuConfig)
      engine.initialize()
      finish(
        engine = engine,
        path = Path.CPU,
        modelFile = cpuFile,
        started = started,
        npuError = npuError,
      )
    }

  private fun npuUnsupportedReason(): String? {
    val soc = Build.SOC_MODEL
    if (soc !in PACKAGED_SOC_MODELS) {
      return "no Google Tensor .litertlm build packaged for SoC '$soc' (have: $PACKAGED_SOC_MODELS)"
    }
    if (Build.VERSION.SDK_INT < 36 || Build.ID.startsWith("BP2A")) {
      return "device or Android build (SDK ${Build.VERSION.SDK_INT}, ${Build.ID}) is not supported by Google Tensor NPU"
    }
    return null
  }

  private fun resolveModelFile(context: Context, fileName: String): File {
    val extDir = context.getExternalFilesDir("litertlm")
    if (extDir != null) {
      val extCandidate = File(extDir, fileName)
      if (extCandidate.isFile && extCandidate.length() > 0L) return extCandidate
      val plainCandidate = File(extDir, "$MODEL_NAME.litertlm")
      if (plainCandidate.isFile && plainCandidate.length() > 0L) return plainCandidate
    }
    val tmpCandidate = File("/data/local/tmp/litertlm", fileName)
    if (tmpCandidate.isFile && tmpCandidate.length() > 0L) return tmpCandidate
    val tmpPlain = File("/data/local/tmp/litertlm", "$MODEL_NAME.litertlm")
    if (tmpPlain.isFile && tmpPlain.length() > 0L) return tmpPlain

    val extractedDir = File(context.filesDir, "litertlm").apply { mkdirs() }
    val targetFile = File(extractedDir, fileName)
    if (targetFile.isFile && targetFile.length() > 0L) return targetFile

    for (assetPath in listOf("litertlm/$fileName", "model/$fileName", "litertlm/$MODEL_NAME.litertlm", "model/$MODEL_NAME.litertlm")) {
      try {
        context.assets.open(assetPath).use { input ->
          val part = File(extractedDir, "$fileName.part")
          part.outputStream().use { output -> input.copyTo(output, bufferSize = 1 shl 20) }
          part.renameTo(targetFile)
          return targetFile
        }
      } catch (_: Exception) {
        // Try next candidate path.
      }
    }
    throw IllegalStateException(
      "LiteRT-LM model '$fileName' not found. Push it via: " +
        "adb push $fileName /sdcard/Android/data/${context.packageName}/files/litertlm/$fileName"
    )
  }

  private fun finish(
    engine: Engine,
    path: Path,
    modelFile: File,
    started: Long,
    npuError: String?,
  ): LoadedLm {
    val ms = SystemClock.elapsedRealtime() - started
    val report =
      JSONObject()
        .put("model", MODEL_NAME)
        .put("kind", "litertlm")
        .put("model_kind", "llm")
        .put("delivery", DELIVERY_MODE)
        .put("path", path.name.lowercase())
        .put("soc", Build.SOC_MODEL)
        .put("file", modelFile.name)
        .put("load_ms", ms)
        .put("npu_error", npuError ?: JSONObject.NULL)
    // Parsed by scripts/install_and_verify.py: keep tag and prefix unchanged.
    Log.i(TAG, "LITERT_TENSOR_RESULT $report")
    return LoadedLm(engine, path, modelFile, ms, npuError)
  }
}
